<script setup>
import { computed, onMounted, ref } from 'vue'
import { useQuasar } from 'quasar'
import { api } from 'boot/axios'
const $q=useQuasar(),rows=ref([]),loading=ref(false),affiliate=ref(null),affiliates=ref([])
const money=c=>(Number(c||0)/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})
const headers={headers:{Authorization:'Bearer '+localStorage.getItem('aito_admin_token')}}
const total=computed(()=>rows.value.reduce((s,r)=>s+(r.amountCents||0),0)),commissions=computed(()=>rows.value.reduce((s,r)=>s+(r.commissionCents||0),0))
const columns=[{name:'date',label:'Confirmada em',field:r=>new Date(r.paidAt).toLocaleDateString('pt-BR'),align:'left'},{name:'customer',label:'Cliente',field:r=>r.customer?.name||r.customerName||'Cliente',align:'left'},{name:'affiliate',label:'Afiliado',field:r=>r.affiliate?.name||'—',align:'left'},{name:'coupon',label:'Cupom',field:'couponCode',align:'left'},{name:'amount',label:'Valor pago',field:r=>money(r.amountCents)},{name:'commission',label:'Comissão',field:r=>money(r.commissionCents)}]
async function load(){loading.value=true;try{rows.value=(await api.get('/admin/affiliate-purchases',{...headers,params:{affiliateId:affiliate.value||undefined}})).data.data||[]}catch(e){$q.notify({type:'negative',message:e.response?.data?.message||'Não foi possível carregar as vendas.'})}finally{loading.value=false}}
onMounted(async()=>{await load();affiliates.value=(await api.get('/admin/affiliates',headers)).data.data||[]})
</script>
<template><section class="affiliate-sales"><header><div><small>AITONOTIFY + WHATSAPP BOTBUILDER</small><h2>Vendas afiliadas</h2><p>Somente compras de licenças com cupom, confirmadas pelo provedor.</p></div><q-btn flat round icon="mdi-refresh" aria-label="Atualizar" @click="load"/></header><div class="sales-summary"><article><span>Valor vendido</span><strong>{{money(total)}}</strong></article><article><span>Comissões</span><strong>{{money(commissions)}}</strong></article><article><span>Vendas confirmadas</span><strong>{{rows.length}}</strong></article></div><q-select v-model="affiliate" outlined dense clearable label="Filtrar afiliado" :options="affiliates.map(a=>({label:a.name,value:a._id}))" emit-value map-options @update:model-value="load"/><q-table flat bordered wrap-cells row-key="_id" :rows="rows" :columns="columns" :loading="loading" no-data-label="Nenhuma venda afiliada do kit"/><small>A tabela mostra até 1.000 vendas. Para totais e períodos completos, abra Dashboard → Afiliados.</small></section></template>
<style scoped>.affiliate-sales{display:grid;gap:22px;color:#284f3c}.affiliate-sales header{display:flex;align-items:center;justify-content:space-between}.affiliate-sales h2{font-size:28px;line-height:1.3;font-weight:750;margin:9px 0}.affiliate-sales p,.affiliate-sales small{color:#6c8a79;font-size:12px}.sales-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.sales-summary article{display:grid;gap:12px;border:1px solid #cde4d5;background:#f3fbf6;border-radius:16px;padding:22px}.sales-summary span{color:#6a8877;font-size:12px}.sales-summary strong{font-size:27px;color:#13805b}.affiliate-sales :deep(.q-table__container){background:#fff;color:#315b43;border-color:#cce5d5;border-radius:14px}@media(max-width:600px){.sales-summary{grid-template-columns:1fr}}</style>
